import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs


class BookStore:
    def __init__(self):
        self._books = {}
        self._next_id = 1

    def create(self, book):
        book_id = self._next_id
        self._next_id += 1
        book = dict(book)
        book["id"] = book_id
        book.setdefault("synopsis", "")
        self._books[book_id] = book
        return book

    def get(self, book_id):
        return self._books.get(book_id)

    def replace(self, book_id, book):
        book = dict(book)
        book["id"] = book_id
        book.setdefault("synopsis", "")
        self._books[book_id] = book
        return book

    def delete(self, book_id):
        return self._books.pop(book_id, None) is not None

    def list_all(self):
        return [self._books[i] for i in sorted(self._books)]

    def search(self, params):
        results = self.list_all()
        for field, value in params.items():
            if field == "id":
                results = [b for b in results if b["id"] == value]
            else:
                results = [b for b in results
                           if _contains_ignore_case(b.get(field), value)]
        return results


def _contains_ignore_case(value, key):
    if value is None:
        return False
    if not isinstance(value, str):
        return False
    return key.lower() in value.lower()


def validate_book_payload(body, allow_id=False):
    """Returns (book_dict, error_message)."""
    if not isinstance(body, dict):
        return None, "error"
    required = ["title", "author", "isbn"]
    if allow_id:
        required.append("id")
    for field in required:
        if field not in body:
            return None, f"{field} is missing"
        if body[field] is None or (isinstance(body[field], str) and body[field] == ""):
            return None, f"{field} is empty"
        if not isinstance(body[field], str):
            return None, f"{field} has wrong type"
    if "id" in body:
        try:
            id_value = int(body["id"])
        except (ValueError, TypeError):
            return None, "id has wrong type"
        if not allow_id or id_value not in book_ids and False:
            return None, "id is not allowed"
    if allow_id:
        return None, "id must not be supplied"
    synopsis = body.get("synopsis", "")
    if not isinstance(synopsis, str):
        return None, "synopsis has wrong type"
    return {
        "title": body["title"],
        "author": body["author"],
        "isbn": body["isbn"],
        "synopsis": synopsis,
    }, None


# global store with reset capability for tests
book_store = BookStore()


def _get_book_id_from_path(path):
    parts = [p for p in path.split("/") if p]
    if len(parts) != 2 or parts[0] != "books":
        return None, 404, "unknown path"
    try:
        book_id = int(parts[1])
    except ValueError:
        return None, 404, "unknown path"
    if book_id not in book_store._books:
        return None, 404, "unknown path"
    return book_id, 200, None


def read_json_body(handler):
    length = int(handler.headers.get("Content-Length", 0) or 0)
    raw = handler.rfile.read(length) if length > 0 else b""
    if not raw:
        return None, 400, "error"
    try:
        return json.loads(raw), None
    except json.JSONDecodeError:
        return None, 400, "error"


