        parsed = urlparse(self.path)
        if parsed.path == "/books":
            self._handle_list(parsed)
        else:
            book_id, status, message = _get_book_id_from_path(parsed.path)
            if status != 200:
                self._send_error(status, message)
                return
            book = book_store.get(book_id)
            if book is None:
                self._send_error(404, "unknown path")
                return
            self._send_json(200, book)

    def _handle_list(self, parsed):
        params, unknown = self._read_query()
        if unknown:
            self._send_error(400, "unknown query parameter")
            return
        result = book_store.search({k: v[0] for k, v in params.items()})
        self._send_json(200, result)

    def do_POST(self):
        if self.path.split("/") != ["", "books"]:
            self._send_error(404, "unknown path")
            return
        body, status, message = read_json_body(self)
        if status != None:
            self._send_error(status, message)
            return
        book, err = validate_book_payload(body, allow_id=False)
        if err is not None:
            self._send_error(400, err)
            return
        created = book_store.create(book)
        self._send_json(201, created)

    def do_PUT(self):
        if self.path.split("/") != ["", "books", str...]:
            pass
        # parse path properly
        parts = self.path.split("/")
        if len(parts) != 3 or parts[0] != "" or parts[1] != "books":
            self._send_error(404, "unknown path")
            return
        book_id, status, message = _get_book_id_from_path(self.path)
        if status != 200:
            self._send_error(status, message)
            return
        body, status, message = read_json_body(self)
        if status != None:
            self._send_error(status, message)
            return
        book, err = validate_book_payload(body, allow_id=False)
        if err is not None:
            self._send_error(400, err)
            return
        updated = book_store.replace(book_id, book)
        self._send_json(200, updated)

    def do_DELETE(self):
        parts = self.path.split("/")
        if len(parts) != 3 or parts[0] != "" or parts[1] != "books":
            self._send_error(404, "unknown path")
            return
        book_id, status, message = _get_book_id_from_path(self.path)
        if status != 200:
            self._send_error(status, message)
            return
        book_store.delete(book_id)
        self._send_json(204, None)
        self.send_response(204)
        self.end_headers()

    def log_message(self, *args):
        pass


def main():
    port = int(os.environ.get("PORT", "8000"))
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()
